      "guidedExample": {
        "title": "Guided walkthrough: How property management fits together",
        "scenario": "A new learner is opening Rentvine for the first time and needs to understand why the program starts with owners and properties before moving into leases, rent, maintenance, accounting, and reporting.",
        "paragraphs": [
          "Let’s start with the big picture before opening any one tab. Property management is the process of caring for rental property on behalf of an owner while serving the resident who lives there.",
          "The owner owns the property. The property manager manages the day-to-day work. The applicant applies to live there. Once approved, the applicant becomes a tenant or resident under a lease. Vendors handle repairs. Accounting records the money in and out.",
          "In Rentvine, these roles become connected records. The Portfolio tab answers owner-level questions. The Properties tab answers property/unit questions. The Screening and Leases areas move an applicant into a financial lease. Accounting records rent, bills, deposits, fees, and distributions. Maintenance records repairs. Reports explain what happened.",
          "A beginner should not memorize the software by tab name only. Instead, think in process order: set up the owner, set up the property, advertise the vacancy, process the applicant, create the lease and documents, invite the resident/owner to portals, collect money, handle work orders, pay bills, report to the owner, and eventually renew or move the tenant out.",
          "The monthly workflow repeats after move-in. Rent is collected, manual payments are deposited, work orders are managed, bills are created and paid, owner statements are produced, and bank/ledger balances are reviewed. This is why later weeks focus heavily on accounting controls and diagnostics."
        ],
        "memoryHook": "Rentvine is easier when you remember the lifecycle: Owner → Property → Vacancy → Applicant → Lease → Resident Operations → Accounting → Reporting → Renewal/Move-Out.",
        "summaryQuestions": [
          "Who are the main people involved in property management?",
          "Which Rentvine record acts as the owner command center?",
          "Why should training labs stay in a sandbox database?",
          "What recurring monthly steps happen after a tenant moves in?"
        ]
      },
