              "body": "Rentvine is built around a few core modules that you'll use every day. Understanding where things live will make the rest of this program much easier to follow.\n      <ul>\n        <li><b>Portfolios</b> &mdash; where owners, ownership percentages, and ledgers live</li>\n        <li><b>Properties</b> &mdash; property details and the Marketing tab for listings</li>\n        <li><b>Leases &amp; Screening</b> &mdash; applicants, applications, and lease terms</li>\n        <li><b>Accounting</b> &mdash; Money In, Money Out, Pay Bills, banking, and management fees</li>\n        <li><b>Owners / Vendors / Residents / Contacts</b> &mdash; the people you work with</li>\n        <li><b>Reports</b> &mdash; every report you can run, save, or schedule</li>\n      </ul>",
              "tip": "The Quick Actions button at the top of the screen is the fastest way to jump straight to common tasks like Pay Bill, without digging through tabs."
