      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Portfolio tab",
        "scenario": "You are onboarding Smith Family Rentals LLC and need to understand where owner-level setup, balances, statements, and payout rules live.",
        "paragraphs": [
          "Let's open the Portfolios tab. This tab is where we manage the owner's overall account. In property management, the owner is the person or company that owns the rental property. The tenant pays rent, we collect that rent, we pay approved expenses, we keep required reserves, and then we send the remaining available funds to the owner.",
          "In Rentvine, all of that owner-level activity is organized inside a portfolio. Think of a portfolio as the main folder for an owner or ownership entity. It connects the owner contact, the properties they own, the accounting ledger, owner statement settings, reserves, and payout rules.",
          "Here we are looking at Smith Family Rentals LLC. First, check the owner contacts. This tells us who owns the portfolio. If there is one owner, that owner may receive 100% of the payout. If there are multiple owners, Rentvine can split the distribution and tax percentages between them.",
          "Next, check which properties belong to the portfolio. If this owner has more than one rental, activity from each property rolls up into the portfolio ledger. The property tells us about the rental asset; the portfolio tells us about the owner's larger account.",
          "Then open the ledger. The ledger is the money history. It shows rent coming in, bills and repairs going out, management fees, owner contributions, reserves, and owner distributions. This is where you go when you need to understand what happened financially.",
          "At the top of the ledger, review the balances. The most important beginner balance is usually the operating balance, because it gives a better picture of what may be available to pay bills or send to the owner. You still need to pay attention to cash, reserves, payables, security deposits, and other holdbacks.",
          "Next, review the reserve amount. A reserve is money intentionally kept back for repairs or future expenses. Do not assume every dollar can be sent to the owner. Additional reserves may also appear when money is being held for a specific project or planned repair.",
          "Then review minimum and maximum distribution settings. These settings control whether Rentvine allows an owner payment and how much can be paid. The posting setting controls where money automatically posts in accounting, and the statement setting controls what type of owner statement the owner receives.",
          "Finally, use the portfolio to review owner communication and portal visibility. Some owners want simple statements; others want detailed reports, bills, work orders, or rent roll information. The portfolio is where those owner-level expectations connect to the accounting activity."
        ],
        "memoryHook": "The Properties tab tells us about the rental property. The Contacts tab tells us about people or companies. The Leases tab tells us about the tenant agreement. The Portfolio tab tells us about the owner's overall account, money, statements, reserves, and payout setup.",
        "summaryQuestions": [
          "Who owns the property or properties?",
          "Which properties belong to this owner group?",
          "What money came in and went out?",
          "How much money should be held back?",
          "What can be paid or reported to the owner?"
        ]
      },
