      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Property record",
        "scenario": "You are adding a rental property to the sandbox and need to make sure the property record is organized before marketing, leasing, maintenance, and accounting begin.",
        "paragraphs": [
          "Let's open the Properties tab. This is where we manage the actual rental asset. If the portfolio is the owner's command center, the property record is the file for the physical rental location.",
          "Start with the property details. Confirm the address, legal description, rental information, images, and assigned property manager. These details affect how the property appears internally, how it is marketed, and who is responsible for follow-up work.",
          "Next, identify the property type. A single-family rental is usually one property with one unit. A multifamily property is usually one property record that contains multiple rentable units. This matters because you do not want to create disconnected records for each unit when they should live together under one multifamily property.",
          "Now connect the property to the correct portfolio. This tells Rentvine which owner account receives the financial activity for this property. Rent collected from tenants, bills paid for repairs, reserves, and owner reporting all depend on this relationship.",
          "Review associations if the property has an HOA. In Rentvine, an association helps represent the HOA relationship. It can be important for payments, notes, compliance details, and property-specific responsibilities.",
          "Then look at property groups and tags. Groups help organize properties structurally, while tags are flexible labels that help you filter and find records quickly. For example, you may tag properties by subdivision, region, acquisition batch, service level, or special handling instructions.",
          "Finally, review maintenance and accounting defaults at the property level. Property-level reserves, maintenance limits, NSF settings, management fee structures, assignees, and watchers help Rentvine route work and apply rules correctly."
        ],
        "memoryHook": "A property record answers: what is the rental, where is it, who manages it, which portfolio owns it, how is it organized, and what default rules apply?",
        "summaryQuestions": [
          "Is this property single-family, HOA-related, or multifamily?",
          "Which portfolio owns it?",
          "Who is assigned to manage it?",
          "Which groups or tags make it easier to find?",
          "Which default accounting or maintenance settings apply?"
        ]
      },
