      "guidedExample": {
        "title": "Guided walkthrough example: Marketing and syndication",
        "scenario": "You have a vacant unit that needs to be advertised and syndicated to rental listing sites.",
        "paragraphs": [
          "Let's open the property and go to the Marketing area. This is where a vacant rental becomes a listing that prospects can find and respond to. Before you publish anything, confirm the property details, rent amount, availability date, photos, amenities, and showing instructions.",
          "Start by checking the basics. A listing needs accurate rent, address, bed and bath count, availability, deposit expectations, and contact information. If these details are wrong, the listing may create low-quality leads or frustrated prospects.",
          "Next, review the photos and listing description. Good photos help prospects understand the unit. The AI-assisted description can help you draft a headline or marketing copy, but it should never be published without review. Read it for accuracy, tone, and fair-housing compliance.",
          "Then confirm the showing provider or self-tour setup. Showing settings control how prospects schedule a tour. If availability windows or showing instructions are not clear, prospects may submit questions instead of booking, which creates more manual work for the leasing team.",
          "Now look at syndication. Syndication means Rentvine is distributing the listing to external rental marketing sites. Publishing the listing is the first step, but partner sites may take time to update. Do not assume a listing will appear everywhere immediately.",
          "Finally, connect marketing to the next workflow. The goal of marketing is not just to publish a pretty listing. The goal is to generate qualified prospects who can apply, complete screening, and eventually become tenants on a lease."
        ],
        "memoryHook": "Marketing turns an available property into a public listing; syndication pushes that listing outward to partner sites.",
        "summaryQuestions": [
          "Is the unit actually available to market?",
          "Are rent, dates, photos, and amenities accurate?",
          "Has the description been reviewed for accuracy and fair-housing compliance?",
          "Is showing availability configured?",
          "Has syndication been activated and checked?"
        ]
      },
