      "guidedExample": {
        "title": "Guided walkthrough example: Applications and screening",
        "scenario": "A prospect has submitted an application, and you need to move from application intake to a documented leasing decision.",
        "paragraphs": [
          "Let's open the Applications area. This is where a prospect becomes an applicant and where the team reviews application details, screening results, income information, co-applicants, guarantors, and decision status.",
          "Start with the application template. The template controls what the applicant is asked to complete, which fees are charged, what fields are required, and what information the team expects to review. A strong template makes the decision process more consistent.",
          "Next, open the applicant record. Review the applicant's contact information, submitted answers, income details, documents, and any co-applicant information. If the applicant needs a guarantor, the guarantor should be added and reviewed through the correct process instead of handled informally.",
          "Then review screening. Screening may include identity, credit, criminal, and eviction-related results depending on the setup and applicable rules. The important beginner concept is that screening information should be interpreted using consistent, documented criteria.",
          "Now communicate the decision. The applicant may be approved, denied, or conditionally approved. A conditional approval might require a guarantor, a larger deposit, or another documented condition. Avoid ad hoc decisions based on personal impressions.",
          "Finally, remember that application work flows into leasing. Once an applicant is approved, their information can carry forward into lease creation, which reduces duplicate data entry and helps the move-in process start cleanly."
        ],
        "memoryHook": "Applications answer whether a prospect qualifies to become a tenant and what conditions, if any, must be met before lease creation.",
        "summaryQuestions": [
          "Did the applicant complete the correct template?",
          "Are all co-applicants or guarantors included?",
          "Were screening results reviewed against consistent criteria?",
          "Was the decision documented?",
          "Is the application ready to become a lease?"
        ]
      },
      "practiceCompanyStep": {
        "company": "Green Valley Property Management",
        "caseFile": "Smith Family Rentals LLC / 123 Maple Street / Jordan Lee / Reliable Plumbing Co.",
        "instruction": "Continue the practice case file in this module: apply the applications, screening & applicant decisions workflow to Smith Family Rentals LLC or 123 Maple Street, using Jordan Lee and Reliable Plumbing Co. when tenant/vendor context is needed."
      }
