      "guidedExample": {
        "title": "Guided walkthrough: From approved applicant to signed move-in lease",
        "scenario": "The applicant has been approved. Now the property manager must turn that approval into a working lease and a document packet the tenant can sign.",
        "paragraphs": [
          "Let’s open the approved application first. At this point, the person is still an applicant. The goal is to convert the approved application into a lease connected to the correct property or unit.",
          "The financial lease is the accounting side of the tenancy. This is where we set lease dates, monthly rent, deposits, recurring charges, one-time move-in charges, and proration. If this part is wrong, the ledger and later reporting will be wrong.",
          "Next, review the lease ledger. The ledger should show the amounts the resident owes at move-in and the schedule for future recurring charges. A beginner should always pause here and ask: does the money on the ledger match what the lease agreement should say?",
          "Now we use RentSign for the legal document packet. A RentSign template is reusable. Hot fields pull live data from Rentvine, such as tenant names, property address, rent amount, and dates. Parties and signing order control who receives the packet and in what sequence.",
          "After the packet is sent, the job is not finished. We check the signature status so we know whether the tenant, guarantor, owner, or manager still needs to sign. Once complete, the lease is ready for normal resident operations."
        ],
        "memoryHook": "Remember it this way: the financial lease makes the ledger work; RentSign makes the paperwork move.",
        "summaryQuestions": [
          "What does the financial lease control?",
          "Why should the ledger be reviewed before move-in?",
          "What is a RentSign hot field?",
          "What should you check after sending the document packet?"
        ]
      },
