      "guidedExample": {
        "title": "Guided walkthrough example: Owner and resident portals",
        "scenario": "You need to invite users to portals and understand what owners and residents can do through self-service access.",
        "paragraphs": [
          "Let's open portal settings and then review the owner and resident portal experiences. Portals are self-service spaces that reduce manual work by letting owners and residents access information or submit requests securely.",
          "Start with owner portals. Owner portal settings can control access to statements, reports, rent rolls, work orders, live ledgers, and other owner-facing information. Be thoughtful about visibility because owners may use portal information to make financial or operational decisions.",
          "Next, review owner statement delivery. Some settings allow public statement access through a secure email link. This can be convenient, but it should be understood from a security perspective because it changes how easily an owner can open a statement.",
          "Then look at resident portals. Residents may use the portal to pay rent, submit maintenance requests, provide move-out notice, manage insurance-related requirements, or update forwarding and refund details during move-out workflows.",
          "Now practice invitations and troubleshooting. Sending an invitation gives a contact secure access. Many portal tickets are simple access issues, such as an expired invite, wrong email, password problem, or a user looking at the wrong portfolio. Learn how to resend invites and reset access.",
          "Finally, remember that owners with multiple entities may need to switch portfolios from their profile menu. If an owner says information is missing, first confirm they are viewing the correct portfolio or legal entity."
        ],
        "memoryHook": "Portals answer: what can the owner or resident do without calling the office, and what information are we choosing to show them?",
        "summaryQuestions": [
          "Who needs portal access?",
          "What can owners see or download?",
          "What can residents submit or pay?",
          "Are portal invitations and login details working?",
          "Is the user viewing the correct portfolio or lease?"
        ]
      },
