      "guidedExample": {
        "title": "Guided walkthrough example: Contacts and communications",
        "scenario": "You need to send a rent reminder to tenants and verify that communication history is recorded correctly.",
        "paragraphs": [
          "Let's open Contacts and Communications. Contacts are the people and companies connected to the business: tenants, owners, vendors, applicants, guarantors, and internal users. Communication tools help you message those contacts and keep a record of what was sent.",
          "Start with the contact record. Confirm the contact type, email address, phone number, linked lease or portfolio, and communication preferences. A good message can still fail if the contact details are wrong.",
          "Next, decide whether this should be an individual message or a mass message. Individual messages are best for one person's situation. Mass messages are best for a defined group, such as all current tenants, delinquent tenants, owners in one portfolio group, or vendors assigned to a region.",
          "Then use templates. Templates save time and keep wording consistent. Hot fields can insert dynamic information, such as a tenant name, property address, balance, or date. Always preview template output before sending a large message.",
          "Now consider communication location. Some messages belong to a lease, property, owner, or vendor context. Keeping communication in the right context makes it easier to resolve disputes later because the history is attached to the right record.",
          "Finally, review the message history. After sending, confirm that the communication appears in the contact or record history. For texts, remember consent and opt-out rules. For sensitive topics, use clear professional language and avoid informal shortcuts."
        ],
        "memoryHook": "Communication is not just sending a message; it is sending the right message to the right segment and keeping a searchable history.",
        "summaryQuestions": [
          "Who should receive this message?",
          "Is this individual or mass communication?",
          "Is the template accurate and professional?",
          "Is the message attached to the right record?",
          "Can the communication history be reviewed later?"
        ]
      },
