      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough: Recording money that comes in",
        "scenario": "A resident pays rent, an owner sends additional funds, and the team needs the bank deposit to match Rentvine.",
        "paragraphs": [
          "Let’s open Accounting and focus only on money coming in. Money In includes payments and receipts received from tenants, owners, and sometimes other parties.",
          "When a tenant pays rent, we record a receipt on the correct lease. This updates the lease ledger and tells Rentvine that money was received against the tenant balance.",
          "If the payment was cash, check, or money order, the receipt is not enough by itself. After the physical money is deposited at the bank, we also record the deposit in Rentvine so the bank activity and Rentvine activity can reconcile.",
          "Electronic portal payments behave differently. Rentvine can record those deposits as settlements. A beginner should remember that posted activity and settled bank activity may not happen at the exact same moment.",
          "Owner contributions are also Money In, but they belong to the portfolio rather than the tenant lease. Owners may contribute funds to restore reserves, cover a negative balance, or fund upcoming work.",
          "Bulk tenant receipts are useful when one payment covers multiple leases, such as a housing authority check. Instead of recording many separate checks, the one payment can be applied across several lease balances."
        ],
        "memoryHook": "Money In answers: Who paid? Which ledger receives it? Has the bank deposit or settlement been recorded?",
        "summaryQuestions": [
          "What is the difference between a tenant receipt and an owner contribution?",
          "Why do manual receipts also need deposit handling?",
          "When would a bulk tenant receipt be useful?"
        ]
      },
