      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Bills, invoices, and vendor payments",
        "scenario": "A plumbing invoice has arrived, and you need to turn it into an approved bill and pay the vendor correctly.",
        "paragraphs": [
          "Let's open Accounting and go to Money Out. Money Out is where expenses and payments leaving the system are managed. In most cases, if an expense needs to be paid, it should become a bill first.",
          "Start by creating or importing the bill. You can add a bill manually or use rapid invoice entry, invoice processing, drag-and-drop upload, mobile scanning, or email-to-bill depending on the workflow. Automation can save time, but the captured information must still be checked.",
          "Review the payee, property, portfolio, bank account, bill date, due date, general ledger account, amount, and description. A small mistake here can affect owner statements, vendor balances, reports, and trust-accounting accuracy.",
          "Next, look at approvals. If bill approvals are enabled, the bill may need review before it can be paid. Approval workflows create a check-and-balance so expenses are not paid before the right person reviews them.",
          "Then review markups, discounts, and credits. A markup may charge an owner more than the vendor invoice. A discount may retain a portion from the vendor payment. A vendor credit reduces what is owed to that vendor. Each item should be intentional and documented.",
          "Finally, pay the bill. Payments may be processed individually or in batches. ACH or NACHA workflows group approved payments for electronic processing, while check workflows may involve printing checks or remote checks. After payment, confirm the bill status and ledger impact."
        ],
        "memoryHook": "The payables flow is invoice received, bill created, details verified, approval completed, payment processed, and ledger checked.",
        "summaryQuestions": [
          "Is the bill tied to the correct property and portfolio?",
          "Is the GL account correct?",
          "Does the bill require approval?",
          "Are any markups, discounts, or credits applied?",
          "Was the payment batch completed accurately?"
        ]
      },
