      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Maintenance work orders",
        "scenario": "A tenant submits a maintenance request, and you need to route it from request to vendor invoice and bill.",
        "paragraphs": [
          "Let's open the Maintenance tab. Maintenance is where service requests become work orders, work orders become assignments, vendors update progress, and completed work can become bills.",
          "Start with the request. A tenant may submit a service request through the resident portal, or a team member may create a work order manually. Confirm the property, unit, issue description, access instructions, photos, priority, and whether the tenant may be financially responsible.",
          "Next, decide how the work should be handled. Some work orders can be assigned directly to a vendor or internal technician. Others may require estimates, owner approval, or multiple vendor bids before work begins.",
          "Then review approval thresholds. If the estimated cost exceeds the owner's approval limit, route the estimate for owner approval before authorizing the work. This protects the owner relationship and documents why the expense was approved.",
          "Now use scheduling and communication tools. If resident presence is required, schedule time windows and reminders so the vendor and tenant know what to expect. The work order timeline and chat history help keep the communication trail in one place.",
          "After the vendor completes the work, review the invoice. Vendors may upload invoices through the vendor portal. The invoice can be converted into a bill, and the bill should be tied back to the property and work order so maintenance and accounting stay connected.",
          "Finally, close the work order only when the status, invoice, bill, and communication history all make sense. A closed work order should tell the complete story of what happened."
        ],
        "memoryHook": "The maintenance path is request, triage, estimate if needed, approval if needed, vendor assignment, completion, invoice, bill, and closeout.",
        "summaryQuestions": [
          "What is the issue and which property or unit is affected?",
          "Does this require an estimate or owner approval?",
          "Who is assigned to complete the work?",
          "Has the vendor invoice been reviewed and converted to a bill?",
          "Does the work order history explain the full outcome?"
        ]
      },
