      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Reports and analytics",
        "scenario": "You need to build a delinquency report and create a reporting package that can be reused.",
        "paragraphs": [
          "Let's open Reports. Reports help turn Rentvine activity into answers. The first beginner rule is to choose the correct report level. A lease-level report answers lease questions; a portfolio-level report answers owner-account questions; a property-level report answers property questions.",
          "Start by deciding the question you need to answer. For example: which tenants are past due, which owners need statements, which bills are unpaid, or which properties are grouped by manager? The report should be built around the question, not around random columns.",
          "Next, choose filters. Filters narrow the data to the records you need, such as active leases, a date range, a property manager, a portfolio, or overdue balances. Without filters, the report may be too broad to act on.",
          "Then adjust columns and grouping. Columns define what you see. Grouping organizes rows by a shared attribute, such as portfolio, property manager, lease status, or balance category. Dragging and rearranging columns can make the report easier to read.",
          "Now use Aged Receivables when reviewing delinquency. Aged Receivables groups balances into aging buckets so you can see how old the outstanding balances are. This helps collections work because a balance due 90 days ago needs different attention than a balance due yesterday.",
          "Finally, save or schedule the report. A favorite is usually personal to you, while a saved report can be shared depending on setup. Scheduled reports can be emailed automatically, which is useful for recurring owner, manager, or accounting workflows."
        ],
        "memoryHook": "Reports answer business questions when you choose the right level, filters, columns, grouping, and schedule.",
        "summaryQuestions": [
          "What question is this report supposed to answer?",
          "What report level should be used?",
          "Which filters are required?",
          "Which columns and groupings make the result useful?",
          "Should this report be saved or scheduled?"
        ]
      },
