      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough example: Manager Dashboard and diagnostics",
        "scenario": "You are reviewing accounting health before month-end and need to find issues before owner statements are sent.",
        "paragraphs": [
          "Let's open the Manager Dashboard and diagnostics area. Think of diagnostics as a system health check for accounting. It helps surface issues that could cause incorrect owner payments, inaccurate statements, or reconciliation problems.",
          "Start with management fees. The dashboard may show fees that have been earned but not posted, unpaid management-fee bills, or payment activity that still needs attention. Posting fees turns earned fees into accounting activity that can be paid or tracked.",
          "Next, review negative balances. A negative bank account or negative portfolio balance means more money may have been paid out, distributed, or recorded than was available. This is not a normal healthy state; it should be investigated before distributions or owner statements are finalized.",
          "Then look at reserve alerts. If reserves are not met, Rentvine is warning that the portfolio may not be holding the required amount. This affects owner distributions because the system should not send out money that needs to remain available for repairs or future expenses.",
          "Now review escrow and prepayment mismatches. Escrow mismatches may indicate that security deposit or trust funds do not tie correctly. Prepayment mismatches may indicate money was applied or held incorrectly. These issues matter because client funds must be tracked accurately.",
          "Also review operational alerts, such as old bank reconciliations, expired vendor insurance, suppressed fee mismatches, or unused vendor credits. These are not just technical warnings; they tell you where accounting cleanup or operational follow-up may be needed.",
          "Finally, use diagnostics as a to-do list. Do not wait until month-end to look at it. A short weekly review can prevent bigger cleanup work later."
        ],
        "memoryHook": "Diagnostics tells you what looks financially unhealthy and where to investigate before money moves or statements go out.",
        "summaryQuestions": [
          "Are management fees posted and paid correctly?",
          "Are any bank or portfolio balances negative?",
          "Are reserves being met?",
          "Do escrow and prepayment balances tie?",
          "Are there stale reconciliations, expired insurance, or unused credits?"
        ]
      },
