      "guidedExample": {
        "title": "Guided walkthrough example: Move-outs and renewals",
        "scenario": "A lease is ending, and you need to either complete the move-out workflow or process a renewal offer.",
        "paragraphs": [
          "Let's open the lease and look at the move-out and renewal options. This module is about tenant transitions. A tenant may leave the property, renew the lease, or move into a new lease situation. Each path affects accounting and future charges.",
          "Start with the move-out workflow. Rentvine uses a structured process that includes move-out details, forwarding information, accounting adjustments, and finalization settings. Work through the steps in order instead of jumping ahead manually.",
          "Next, review charges and credits carefully. Charges added inside the move-out flow may not save unless the move-out process is completed. If a credit is applied, Rentvine may automatically allocate funds, but you may need to review or reallocate them so the accounting is correct.",
          "Then calculate the security deposit outcome. The refund is not automatically the full deposit. It should be the deposit held minus allowable deductions, unpaid charges, damages, or other documented items. Refunds may also need to be split between roommates when applicable.",
          "If the move-out is processed incorrectly, do not assume you can fix every part casually afterward. In some cases, the move-out must be canceled and restarted from the beginning. Accuracy matters before finalizing.",
          "Now review renewals. Leases appear on the renewal dashboard based on the configured renewal eligibility days. You can create renewal offers, provide multiple options, send offers to the tenant portal, route documents through RentSign, and finalize the renewal after acceptance.",
          "When a renewal is finalized, confirm that lease dates, recurring charges, rent increases, and status all update correctly. A renewal is not complete until the future ledger activity matches the approved terms."
        ],
        "memoryHook": "Move-out closes a lease cleanly; renewal extends it cleanly. Both require accurate dates, charges, documents, and ledger results.",
        "summaryQuestions": [
          "Is the tenant moving out or renewing?",
          "Have all move-out steps been completed in order?",
          "Are deposit deductions and refunds documented?",
          "If renewing, are offers and RentSign documents complete?",
          "Do the lease status, dates, charges, and ledger balance make sense?"
        ]
      },
