      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough: Decide whether the tenant renews or moves out",
        "scenario": "A resident is nearing the end of the lease term. The team needs to know whether to offer renewal options or prepare for move-out.",
        "paragraphs": [
          "Let’s open the lease and look at the current end date. If the resident is staying, the process is a renewal. If the resident is leaving, the process is a move-out. These are different business outcomes and different workflows.",
          "For renewal, Rentvine uses eligibility settings to decide which leases should appear for review. The team can create offer options, such as different rent amounts or terms, and send those options to the resident through the portal.",
          "Once the resident accepts an offer, the lease usually needs documents. RentSign can send renewal agreements or addenda. After signatures, the lease dates and recurring charges should match the approved renewal terms.",
          "Bulk tenant receipts are a separate but common operational tool. If a housing authority or other payer sends one lump-sum payment for several residents, the user can apply the single receipt across multiple lease balances instead of recording separate checks.",
          "A beginner should remember the decision tree: is the resident staying? Start renewal. Is the resident leaving? Start move-out. Is one payment covering multiple leases? Use bulk receipt."
        ],
        "memoryHook": "Renewal keeps the tenancy going; move-out closes it; bulk receipt applies one payment across multiple lease balances.",
        "summaryQuestions": [
          "What makes a lease appear for renewal review?",
          "What updates after a renewal is finalized?",
          "When should bulk tenant receipt be used?"
        ]
      },
