      "labVideoRequirement": "Submit a short screen recording or walkthrough video showing the required lab completed in the training/sandbox database. Paste the video URL, upload confirmation, or video file name in the fields below.",
      "guidedExample": {
        "title": "Guided walkthrough: Why trust accounting is the control layer",
        "scenario": "The learner has already practiced receipts, deposits, bills, maintenance, statements, and diagnostics. Now they need the accounting principles that explain why accuracy matters.",
        "paragraphs": [
          "Let’s start with the idea of trust accounting. Property managers often hold money that belongs to someone else: owner funds, tenant payments, and security deposits. That money must be tracked carefully and kept separate from company operating money.",
          "The Chart of Accounts is the labeling system. It tells Rentvine whether money is rent, security deposit, pet fee, management fee, repair expense, prepaid rent, or something else. If the label is wrong, the ledger and reports may look wrong even if the dollar amount is right.",
          "Payment allocation order matters because one payment may need to cover multiple charges. The system needs rules for what gets paid first. Those rules should match company policy and accounting expectations.",
          "Prepaid rent is a common beginner trap. If a tenant pays next month’s rent early, that money may be in the bank, but it should not be treated as earned income until the charge posts. Until then, it behaves like a liability.",
          "Reconciliation is the review process that proves the records tie. Bank balances, ledger balances, and property or portfolio balances need to agree. Diagnostics can help find problems, but reconciliation proves the system is trustworthy."
        ],
        "memoryHook": "Trust accounting asks: Whose money is it? What is it for? Where is it held? Does the ledger tie to the bank?",
        "summaryQuestions": [
          "Why is prepaid rent not always immediate income?",
          "What does the Chart of Accounts do?",
          "Why does reconciliation matter before owner reporting?"
        ]
      },
