      "guidedExample": {
        "title": "Guided walkthrough: Admin setup before scale",
        "scenario": "The team has learned the operational workflows. Now they need to control who can do what and how external systems connect.",
        "paragraphs": [
          "Let’s open settings with an administrator mindset. This part of Rentvine is not about one tenant or one owner. It is about how the whole account behaves.",
          "Start with users and roles. A beginner might think it is easiest to give everyone full access, but that creates risk. Least privilege means each user receives only the permissions needed for their job.",
          "Next, review integrations. QuickBooks export supports accounting software workflows for management company income and payouts. Property Meld can reduce duplicate entry by sending approved invoices or expenditures into Rentvine as bills. But integrations have boundaries, so always ask what syncs, what does not sync, and which system owns the source of truth.",
          "API access is powerful because it lets approved vendors or developers connect directly to Rentvine data. An API key should be created only for a specific purpose and specific partner. Sharing an API key means you intend to share data with that party.",
          "Finally, use a go-live checklist. Validate bank and payment readiness, portal settings, owner/property/lease test records, notifications, roles, and migration questions before relying on the account for real operations."
        ],
        "memoryHook": "Administration answers: who has access, what integrates, what syncs, and is the account safe for go-live?",
        "summaryQuestions": [
          "Why should roles follow least privilege?",
          "What should an integration map show?",
          "Why should API keys be controlled?",
          "What belongs on a go-live checklist?"
        ]
      },
