      "Explain the property management lifecycle and records involved",
      "Create portfolio and configure owner/payout rules",
      "Create property/unit and link to portfolio",
      "Configure marketing/listing workflow",
      "Process application and screening decision",
      "Create financial lease and move-in charges",
      "Send RentSign packet and confirm status",
      "Invite portal users and verify access/settings",
      "Record tenant receipt and deposit/settlement context",
      "Create bill and pay vendor/payment batch",
      "Create or close a maintenance work order",
      "Post management fee and generate owner statement",
      "Run report and review diagnostics",
      "Process move-out or renewal scenario",
      "Explain trust accounting/reconciliation result",
      "Document integration/role/go-live considerations"
