  "onboarding": {
    "title": "Before You Begin: Property Management Orientation",
    "intro": "Start here if you are unfamiliar with property management. This short orientation explains the business model before the Rentvine-specific workflow begins.",
    "outcomes": [
      "Identify the main people in a property management workflow: owner, tenant, applicant, vendor, and manager.",
      "Explain how money moves from tenant payment to owner statement.",
      "Distinguish portfolio, property, unit, lease, ledger, and portal.",
      "Recognize why trust accounting controls and sandbox practice matter."
    ],
    "sections": [
      {
        "heading": "The basic property management lifecycle",
        "body": "A property manager helps an owner operate a rental property. The manager advertises vacancies, screens applicants, creates leases, collects rent, coordinates maintenance, pays approved bills, keeps required reserves, reports to the owner, and manages renewals or move-outs."
      },
      {
        "heading": "The main people and records",
        "body": "Owners own the rental asset. Applicants want to rent. Tenants live in the unit under a lease. Vendors perform work. The management company coordinates the process. In Rentvine, portfolios hold owner-level accounting, properties and units describe the physical rental, leases connect tenants to the property, and ledgers show the money history."
      },
      {
        "heading": "The money story",
        "body": "Rent comes in from tenants. Approved expenses go out to vendors. Reserves and liabilities are held back when needed. Management fees may be posted. The remaining available funds can be distributed to the owner and summarized on an owner statement."
      },
      {
        "heading": "Sandbox rule",
        "body": "All training labs should be completed in a training or sandbox database. Never create test leases, payments, bills, owner distributions, or move-outs in a production account."
      }
    ],
    "checks": [
      "I can explain the difference between owner, applicant, tenant, and vendor.",
      "I can explain the difference between a portfolio, property, unit, lease, and ledger.",
      "I understand that training transactions belong in a sandbox or training database.",
      "I reviewed the property management lifecycle before starting Week 1."
    ]
  },
